{"expression": "(async () => {
  const t0 = Date.now();
  const alvos = ['Conversas', 'Pesquisar', 'Chats'];
  const sleep = ms => new Promise(r => setTimeout(r, 400));
  while (Date.now() - t0 < 15000) {
    const txt = document.body ? document.body.innerText : '';
    const achado = alvos.filter(a => txt.includes(a));
    const temLinha = !!document.querySelector('[role="row"][data-testid^="list-item-"]');
    if (achado.length > 0 || temLinha) {
      return { ready: true, ms: Date.now() - t0, achados: achado, linhas: document.querySelectorAll('[role="row"][data-testid^="list-item-"]').length, qr: !!document.querySelector('canvas[aria-label], [data-ref]') };
    }
    await sleep(400);
  }
  return { ready: false, ms: Date.now() - t0, achados: [], linhas: 0, texto: (document.body.innerText || '').slice(0, 300) };
})()"}

